    h=len(g); w=len(g[0]); out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if g[i][j]!=0:
                k=1
                while True:
                    ni,nj=i+k,j+k
                    if ni>=h or nj>=w or g[ni][nj]!=0: break
                    out[ni][nj]=g[i][j]; k+=1
                out[i][j]=g[i][j]
    return out
